"""Message personalization — every outgoing message is generated by Claude
from the strategy's Phase-6 messaging research + the lead's enrichment,
guided by the sequence step's brief. The rendered subject/body are
persisted on the message row BEFORE any send happens.
"""

import logging
import re
from urllib.parse import urlparse

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db.models import Lead, PipelineKind, ResearchStep, SequenceStep, Strategy
from app.services import grounding, prompt_safety
from app.services.anthropic_client import get_client

logger = logging.getLogger(__name__)

# I1 consent hardening (T03 c-model-foreign-unsubscribe-link, i-obeyed-link):
# a URL in the model's body must point at the sender's own booking page or
# the sender's / this app's own domain. Anything else (a model-written
# "unsubscribe" link to a third party, a link copied from injected lead text)
# is removed before the body is persisted or sent. The real one-click
# unsubscribe is added by sequence_engine.build_compliant_email.
#
# Links are found with reply_copilot.urls_in, which also catches links with no
# scheme ("www.evil.com", "bit.ly/x9", "optout-now.io/remove"): mail and
# messaging clients turn those into clickable links too.
_OPT_OUT_WORDS = re.compile(r"(?i)\b(?:unsubscribe|opt[ -]?out|remove (?:me|you)|stop (?:receiving|these))\b")


def _host(url: str | None) -> str:
    try:
        return (urlparse(url or "").hostname or "").lower().rstrip(".")
    except ValueError:
        return ""


def _own_domains(session: Session, strategy: Strategy) -> set[str]:
    """This app's public hosts plus the account owner's business domains
    (login address and connected mailboxes; consumer webmail excluded)."""
    from app.config import settings  # noqa: PLC0415
    from app.services import deliverability  # noqa: PLC0415

    hosts = {_host(settings.frontend_url), _host(settings.public_base_url)}
    try:
        product = strategy.product
        user = product.user if product is not None else None
        if user is not None:
            email = (user.email or "").strip().lower()
            if "@" in email:
                domain = email.rsplit("@", 1)[1]
                if domain not in deliverability.CONSUMER_DOMAINS:
                    hosts.add(domain)
            hosts.update(d for d, _ in deliverability.sending_domains(session, user.id))
    except Exception:  # noqa: BLE001 -- fail closed: fewer allowed links
        logger.warning("could not resolve the sender's own domains", exc_info=True)
    return {h for h in hosts if h}


def links_in(text: str | None) -> list[str]:
    """Every link in `text`, with or without a scheme."""
    from app.services.reply_copilot import urls_in  # noqa: PLC0415

    return urls_in(text)


def _host_and_path(link: str) -> tuple[str, str]:
    """(host, path) as a browser reads `link`, with or without a scheme.

    Not urlparse: it takes "https://evil.com\\@acme.com/x" to be on acme.com,
    while browsers treat the backslash as a path separator and open
    evil.com. The authority ends at the first / \\ ? or #, and the host is
    what follows its last "@"."""
    bare = re.sub(r"^https?:", "", (link or "").strip(), flags=re.I).lstrip("/\\")
    authority = re.split(r"[/\\?#]", bare, maxsplit=1)[0]
    host = authority.rsplit("@", 1)[-1].split(":", 1)[0].lower().rstrip(".")
    path = re.split(r"[?#]", bare[len(authority):], maxsplit=1)[0].replace("\\", "/")
    return host, path


def _link_allowed(url: str, booking_url: str | None, own: set[str]) -> bool:
    host, path = _host_and_path(url)
    if not host:
        return False
    if booking_url:
        b_host, b_path = _host_and_path(booking_url)
        if host == b_host and path.rstrip("/").startswith(b_path.rstrip("/")):
            return True
    # Exact host, or its www. form. Other subdomains are not trusted: a
    # shared parent domain would otherwise admit any host under it.
    return host in own or (host.startswith("www.") and host[4:] in own)


def strip_foreign_links(body: str, booking_url: str | None, own_domains: set[str]) -> str:
    """Remove every URL outside the allowlist from a model-written body.
    A line that offered an opt-out through such a link is dropped whole (the
    compliant footer carries the real one). Deterministic; no model call."""
    out: list[str] = []
    removed: list[str] = []
    for line in body.split("\n"):
        bad = [u for u in links_in(line) if not _link_allowed(u, booking_url, own_domains)]
        if not bad:
            out.append(line)
            continue
        removed.extend(bad)
        if _OPT_OUT_WORDS.search(line):
            continue
        for u in bad:
            line = line.replace(u, "")
        line = re.sub(r"[ \t]{2,}", " ", line)
        line = re.sub(r"\s+([.,;:!?])", r"\1", line).rstrip(" :").rstrip()
        out.append(line)
    if removed:
        logger.warning("removed %d off-allowlist link(s) from a generated body", len(removed))
    return "\n".join(out).strip()

_SYSTEM = (
    "You are Victorae's message personalization engine. You write one "
    "concise, specific, non-spammy B2B outreach email for one lead, "
    "following the messaging playbook and the step brief. Respond with "
    'ONLY a JSON object: {"subject": "...", "body": "..."} — no prose, '
    "no markdown fences. The body is plain text, under 140 words, no "
    "placeholders like [Name] (use the actual data given), and does NOT "
    "include an unsubscribe footer (the system appends the compliant "
    "footer itself)."
)

_PROMPT = """{notice}

SEQUENCE STEP #{step_no} BRIEF (variant {variant}):
{template}

MESSAGING PLAYBOOK (from strategy research, phase 6):
{playbook}

LEAD:
- Name: {full_name}
- Title: {title}
- Company: {company}
- Enrichment highlights: {enrichment}

{context}{booking_line}
Write the email for THIS lead now."""

# A hard ceiling on a generated email body. The prompt asks for under 140
# words; this leaves room for normal variance and refuses a runaway answer.
MAX_BODY_WORDS = 200

# Phase 3 item 2: the reply render_message reads. The code falls back on a
# missing subject and raises on an empty body.
MESSAGE_SCHEMA = {
    "type": "object",
    "properties": {"subject": {"type": "string"}, "body": {"type": "string"}},
    "required": ["subject", "body"],
    "additionalProperties": False,
}


def _playbook(session: Session, strategy: Strategy) -> str:
    rows = session.execute(
        select(ResearchStep).where(
            ResearchStep.strategy_id == strategy.id,
            ResearchStep.pipeline == PipelineKind.STRATEGY,
            ResearchStep.phase == 6,
            ResearchStep.step_no % 9 == 0,  # phase-6 synthesis
        )
    ).scalars().all()
    research = ("\n\n".join(r.output for r in rows)
                or "(no messaging research found — keep it short, factual and human)")
    mutation = _applied_mutation(session, strategy)
    playbook = f"{mutation}\n\n{research}" if mutation else research
    # Local business mode (docs/features/local-business-mode.md): the local
    # context and its hard limits come first. Empty for every other product.
    from app.services import local_business  # noqa: PLC0415

    local = local_business.block_for_strategy(session, strategy)
    return f"{local}\n\n{playbook}" if local else playbook


def _voice(session: Session, strategy: Strategy) -> str:
    from app.services.style_profile import suffix_for_strategy  # noqa: PLC0415

    return suffix_for_strategy(session, strategy)


def _applied_mutation(session: Session, strategy: Strategy) -> str | None:
    """Feature Group 1: the messaging of an APPLIED strategy mutation.

    Outreach is personalised from the phase-6 research above, not from
    strategy_document -- so applying a mutation by rewriting the document
    alone would have changed nothing a lead ever receives. The applied
    version's new angle and revised messaging are therefore put in front of
    the research here, marked as taking precedence where they conflict. A
    proposed (unapplied) mutation has no effect.
    """
    from app.db.models import StrategyVersion  # noqa: PLC0415

    version = session.execute(
        select(StrategyVersion)
        .where(StrategyVersion.strategy_id == strategy.id,
               StrategyVersion.status == "applied",
               StrategyVersion.trigger != "original")
        .order_by(StrategyVersion.version_no.desc())
    ).scalars().first()
    if version is None:
        return None
    changes = version.changes_json or {}
    angle = (changes.get("messaging_angle") or {}).get("proposed") or ""
    revised = changes.get("revised_messaging") or ""
    return (f"[APPLIED STRATEGY MUTATION v{version.version_no} — takes precedence "
            f"over the research below where they conflict]\n"
            f"Messaging angle: {angle}\n{revised}").strip()


def render_message(
    session: Session,
    strategy: Strategy,
    lead: Lead,
    step: SequenceStep,
    booking_url: str | None = None,
    inputs_out: dict | None = None,
    why_now: str | None = None,
) -> tuple[str, str]:
    """Returns (subject, body) — the caller persists them before sending.

    F02 Signal Radar: `why_now` is signal_radar.prompt_block() for the one
    signal offered to this email (its untrusted text already delimited), or
    None. Only the email send path passes it.

    Feature 3: the step's brief is enriched with the product's founder voice
    profile (app/services/voice_profiler.py) when one has been analysed, so
    the copy reads like the person whose name is on it. Recorded in
    `inputs_out` as `voice_profile`.

    Feature Group 2: the prompt carries the lead's recent LinkedIn posts and
    company news (personalization_context), the personal-video CTA on step 2
    when one was recorded (loom_video), and the system prompt carries the
    sender's voice profile (style_profile). `inputs_out`, when given, is
    filled with what the message was written from, for messages.personalization_json.
    """
    from app.services import (  # noqa: PLC0415
        loom_video, personalization_context, style_profile, voice_profiler,
    )

    enrichment = lead.enrichment_json or {}
    highlights = {
        k: enrichment.get(k)
        for k in ("company_domain", "enrichment")
        if enrichment.get(k)
    }
    booking_line = (
        f"Include this scheduling link naturally in the call to action: {booking_url}\n"
        if booking_url else ""
    )
    context, used = personalization_context.prompt_block(lead)
    cta = loom_video.cta_for_step(lead, step.step_no)
    used["loom_cta"] = bool(cta)
    if cta:
        context = f"{context}\n\n{cta}".strip()
    if why_now:
        context = f"{context}\n\n{why_now}".strip()
    voice = style_profile.suffix_for_strategy(session, strategy)
    used["style_profile"] = bool(voice)
    # Feature 3: the founder's own voice, cloned from their LinkedIn posts and
    # appended to the STEP BRIEF rather than the system prompt. The brief is
    # where "how to write this particular message" already lives, and keeping
    # the two voice sources in different places is deliberate: the account-wide
    # style profile above says "write like this person", and this says "and
    # specifically, in this product's founder voice". Never raises -- a missing
    # or broken profile returns the template unchanged.
    template, voice_profile_used = voice_profiler.brief_for_strategy(
        session, strategy, step.template)
    used["voice_profile"] = voice_profile_used
    if inputs_out is not None:
        inputs_out.update(used)
    data = get_client().complete_json(
        system=_SYSTEM + voice,
        prompt=_PROMPT.format(
            notice=prompt_safety.NOTICE,
            context=f"{context}\n\n" if context else "",
            step_no=step.step_no,
            variant=step.variant,
            template=template,
            playbook=_playbook(session, strategy),
            # F-AI-02: every lead field below is scraped from a profile the
            # prospect controls, so each is delimited and folded onto one line.
            # The step brief and playbook are OURS and stay unwrapped.
            full_name=prompt_safety.inline(lead.full_name or "there"),
            title=prompt_safety.inline(lead.title or "unknown"),
            company=prompt_safety.inline(lead.company or "their company"),
            enrichment=prompt_safety.inline(str(highlights)[:1500]),
            booking_line=booking_line,
        ),
        schema=MESSAGE_SCHEMA,
    )
    subject = str(data.get("subject") or "").strip() or "Quick question"
    body = str(data.get("body") or "").strip()
    if body:
        body = strip_foreign_links(body, booking_url, _own_domains(session, strategy))
    if not body:
        raise ValueError("personalization returned an empty body")
    words = len(body.split())
    if words > MAX_BODY_WORDS:
        # The prompt asks for under 140 words; that rule is not a control.
        # Refuse rather than cut: a cut body loses its ask. The send task's
        # retry asks the model again.
        raise ValueError(f"personalization returned a {words}-word body "
                         f"(limit {MAX_BODY_WORDS})")
    return subject, body


# --------------------------------------------------------------------------
# WhatsApp template variables (M4 Chunk 3)
# --------------------------------------------------------------------------

_WA_SYSTEM = (
    "You are Victorae's WhatsApp template variable filler. You produce "
    "SHORT values for numbered template variables, from real lead data and "
    "the messaging playbook. Respond with ONLY a JSON object mapping each "
    'requested variable number to its value, e.g. {"1": "Sara", "2": '
    '"Acme\'s slow onboarding"}. Values must be plain text, a few words '
    "each, honest, drawn only from the data given — never invented facts, "
    "names, or statistics."
)

_WA_PROMPT = """{notice}

TEMPLATE BODY (for context — do NOT rewrite it):
{body}

VARIABLES TO FILL (number -> what it means / brief):
{briefs}

MESSAGING PLAYBOOK (strategy research, phase 6):
{playbook}

LEAD:
- Name: {full_name}
- Title: {title}
- Company: {company}
- Enrichment highlights: {enrichment}

Return the JSON object of values now."""

# Phase 3 item 2: the variable numbers are the template's own {{n}}, known only
# at call time, so {{1}}..{{20}} are listed and none is required (the code
# raises on any requested number left empty). A template with more than 20
# variables cannot be filled by a constrained model.
WHATSAPP_VARIABLES_SCHEMA = {
    "type": "object",
    "properties": {str(n): {"type": "string"} for n in range(1, 21)},
    "additionalProperties": False,
}

# Deterministic 'lead.<field>' sources — no model call needed for these.
_LEAD_FIELDS = {
    "lead.full_name": lambda lead: lead.full_name,
    "lead.first_name": lambda lead: (lead.full_name or "").split(" ")[0],
    "lead.title": lambda lead: lead.title,
    "lead.company": lambda lead: lead.company,
    "lead.email": lambda lead: lead.email,
}


# A model-filled template slot is "a few words". Lead-field values
# ('lead.company' and so on) are the lead's own data and are not capped.
MAX_WA_VARIABLE_CHARS = 100


def render_whatsapp_variables(
    session: Session,
    strategy: Strategy,
    lead: Lead,
    template_body: str,
    variable_descriptions: dict,
    variable_mapping: dict | None,
) -> dict[str, str]:
    """Values for every {{n}} in an approved template.

    mapping semantics (per variable number, from the sequence step):
      'lead.<field>'  -> filled deterministically from the lead row
      anything else   -> treated as a brief; Claude fills it from lead
                         enrichment + the strategy's messaging playbook
      missing mapping -> the template's own variable description is the brief
    Same personalization path as M3 email — one model call for all briefs.
    Raises ValueError when a variable cannot be filled (caller fails the
    send rather than transmitting a template with empty slots)."""
    mapping = {str(k): str(v) for k, v in (variable_mapping or {}).items()}
    numbers = sorted(variable_descriptions or {}, key=lambda n: int(n))

    values: dict[str, str] = {}
    briefs: dict[str, str] = {}
    for n in numbers:
        source = mapping.get(n, "").strip()
        if source in _LEAD_FIELDS:
            value = (_LEAD_FIELDS[source](lead) or "").strip()
            if value:
                values[n] = value
                continue
            # Empty lead field degrades to a brief, not an empty variable.
            source = ""
        briefs[n] = source or str(variable_descriptions.get(n, f"variable {n}"))

    if briefs:
        enrichment = lead.enrichment_json or {}
        data = get_client().complete_json(
            # Feature Group 2: the sender's voice, like every outreach copy call.
            system=_WA_SYSTEM + _voice(session, strategy),
            prompt=_WA_PROMPT.format(
                notice=prompt_safety.NOTICE,
                body=template_body,
                briefs="\n".join(f"{{{{{n}}}}} -> {b}" for n, b in briefs.items()),
                playbook=_playbook(session, strategy),
                # F-AI-02: lead fields and enrichment are scraped from
                # profiles the prospect controls -- delimited, one line each.
                # The template body, briefs and playbook are OURS.
                full_name=prompt_safety.inline(lead.full_name or "unknown"),
                title=prompt_safety.inline(lead.title or "unknown"),
                company=prompt_safety.inline(lead.company or "unknown"),
                enrichment=prompt_safety.inline(str(enrichment)[:1500]),
            ),
            schema=WHATSAPP_VARIABLES_SCHEMA,
        )
        for n in briefs:
            value = str(data.get(n) or "").strip()
            if not value:
                raise ValueError(f"could not fill template variable {{{{{n}}}}}")
            # The prompt's "a few words each" and the claim check are not link
            # or length controls. A slot is a short phrase in a template Meta
            # approved: a URL (an injected one, say) or a paragraph is refused.
            if links_in(value):
                raise ValueError(f"template variable {{{{{n}}}}} contains a link")
            if len(value) > MAX_WA_VARIABLE_CHARS:
                raise ValueError(f"template variable {{{{{n}}}}} is {len(value)} characters "
                                 f"(limit {MAX_WA_VARIABLE_CHARS})")
            values[n] = value

    missing = [n for n in numbers if n not in values]
    if missing:
        raise ValueError(f"unfilled template variables: {missing}")
    return values


def preview_whatsapp_body(template_body: str, values: dict[str, str]) -> str:
    """The human-readable rendered body persisted on the message row."""
    out = template_body
    for n, v in values.items():
        out = out.replace("{{%s}}" % n, v)
    return out


# --------------------------------------------------------------------------
# Engagement Hub, Feature 1 — the auto follow-up brief
# --------------------------------------------------------------------------
#
# WHY THIS RETURNS A BRIEF AND NOT A FINISHED MESSAGE
# Every message in this system is a two-stage thing: a sequence step holds a
# BRIEF ("open on their hiring post, ask one question about onboarding"), and
# render_message above turns the brief plus the lead's data plus the strategy's
# messaging playbook into the copy that actually sends. That split is what lets
# the send path re-render at send time, after the compliance gates, with the
# playbook as it stands today.
#
# An auto follow-up that produced finished copy here would sit outside all of
# that: it would be written hours before it sends, against whatever the
# playbook said then, and it would bypass the personalization scoring and the
# compliant-email assembly that only run on the render path. So this generates
# the missing BRIEF -- the thing a human would have written as step N+1 -- and
# the ordinary send path does the rest.
#
# It costs one extra model call per auto follow-up. That is the price of the
# follow-up being indistinguishable from a step somebody wrote.

_FOLLOWUP_SYSTEM = (
    "You are Victorae's follow-up brief writer. A prospect was contacted and "
    "has not replied. You write the BRIEF for the next touch -- instructions "
    "to the message writer, not the message itself. Respond with ONLY a JSON "
    'object: {"brief": "..."} -- no prose, no markdown fences.\n'
    "RULES. The brief is 1-3 sentences. It must name the angle to take and "
    "the single question to ask. It must be grounded ONLY in the history and "
    "product brief given -- never invent a trigger event, a mutual "
    "connection, a statistic or a deadline. Do not suggest guilt, urgency, "
    "'just bumping this to the top of your inbox', 'circling back', or any "
    "reference to the prospect not having replied. Assume they never saw the "
    "first message."
)

_FOLLOWUP_PROMPT = """{notice}

WHAT WAS SENT BEFORE (most recent last):
{history}

WHAT THIS PROSPECT HAS DONE (outcome log):
{outcomes}

WHAT WE SELL:
{product}

MESSAGING PLAYBOOK (strategy research, phase 6):
{playbook}

LEAD:
- Name: {full_name}
- Title: {title}
- Company: {company}

CHANNEL FOR THIS FOLLOW-UP: {channel}

Write the brief for the next touch now."""

# Phase 3 item 2: both brief writers (follow-up and re-engagement) answer this.
BRIEF_SCHEMA = {
    "type": "object",
    "properties": {"brief": {"type": "string"}},
    "required": ["brief"],
    "additionalProperties": False,
}

# Used when the model call fails. A generic brief still produces a message the
# render path will personalize from real lead data, which is a far better
# outcome than a follow-up that silently never sends because Anthropic was
# briefly down.
FALLBACK_FOLLOWUP_BRIEF = (
    "Short, friendly follow-up on the previous message. Restate the single "
    "most relevant benefit for this company in one line and ask one specific, "
    "easy-to-answer question. No pressure, no reference to them not replying."
)


def _grounded_brief(brief: str, lead: Lead, *sources: str) -> str:
    """`brief`, or '' when it is not grounded in what the writer was given.

    The brief becomes the next step's template, which every renderer follows
    as OUR instructions. Its prompt forbids inventing statistics, rounds,
    discounts and deadlines and adding links; nothing checked. A brief that
    breaks a rule is replaced by the caller's fixed fallback, not repaired:
    the fallback is a safe, personalisable brief and costs no second call."""
    if not brief:
        return ""
    found = grounding.problems(brief, *sources)
    if links_in(brief):
        found.append("a link")
    if found:
        logger.warning("brief for lead %s replaced by the fallback: %s",
                       lead.id, "; ".join(found))
        return ""
    return brief


def build_followup_brief(
    session: Session,
    strategy: Strategy,
    lead: Lead,
    *,
    channel: str = "email",
    max_history: int = 3,
) -> str:
    """The brief for an automatic follow-up, from this lead's actual history.

    Never raises. A follow-up whose brief could not be generated falls back to
    FALLBACK_FOLLOWUP_BRIEF rather than failing the send: the render path will
    still personalize it against the lead's real data and the playbook, so the
    degraded case is a less specific message, not a wrong one and not a
    missing one.
    """
    from app.db.models import Message, Outcome, Product  # noqa: PLC0415

    sent = session.execute(
        select(Message)
        .where(Message.lead_id == lead.id, Message.body.isnot(None))
        .order_by(Message.step_no)
    ).scalars().all()[-max_history:]
    history = "\n\n".join(
        f"[step {m.step_no}, {m.channel.value if m.channel else '?'}] "
        f"{(m.subject or '').strip()}\n{(m.body or '').strip()[:600]}"
        for m in sent
    ) or "(nothing on file — treat this as a first touch)"

    events = session.execute(
        select(Outcome)
        .where(Outcome.lead_id == lead.id)
        .order_by(Outcome.ts)
    ).scalars().all()[-12:]
    outcomes = ", ".join(
        f"{o.event.value if o.event else '?'}"
        f"({o.channel}{', ' + o.ts.date().isoformat() if o.ts else ''})"
        for o in events
    ) or "(no recorded activity)"

    product = session.get(Product, strategy.product_id)
    product_brief = (
        f"{product.name} — {product.description or ''}".strip(" —")
        if product is not None else "(no product on file)"
    )

    try:
        data = get_client().complete_json(
            system=_FOLLOWUP_SYSTEM,
            prompt=_FOLLOWUP_PROMPT.format(
                notice=prompt_safety.NOTICE,
                # F-AI-02: earlier bodies were model-written from lead data,
                # and the lead fields are scraped -- all delimited. Outcomes
                # (our event enums), product brief and playbook are OURS.
                history=prompt_safety.block(history[:6000]),
                outcomes=outcomes,
                product=product_brief[:1000],
                playbook=_playbook(session, strategy)[:4000],
                full_name=prompt_safety.inline(lead.full_name or "there"),
                title=prompt_safety.inline(lead.title or "unknown"),
                company=prompt_safety.inline(lead.company or "their company"),
                channel=channel,
            ),
            schema=BRIEF_SCHEMA,
        )
        brief = str((data or {}).get("brief") or "").strip()
    except Exception as exc:  # noqa: BLE001 — see the docstring
        logger.warning("follow-up brief generation failed for lead %s: %s: %s",
                       lead.id, type(exc).__name__, exc)
        brief = ""

    brief = _grounded_brief(brief[:2000], lead, history, product_brief,
                            _playbook(session, strategy))
    return brief or FALLBACK_FOLLOWUP_BRIEF


# --------------------------------------------------------------------------
# Feature 5 — the re-engagement brief
# --------------------------------------------------------------------------
# Same inputs and the same no-invention rules as the follow-up brief. The
# difference is the situation: the lead finished a whole sequence weeks ago
# without replying, so the touch is ONE light message that makes "not now" or
# "no" as easy to send as "yes" -- not another push.

_REENGAGEMENT_SYSTEM = (
    "You are Victorae's re-engagement brief writer. A prospect received a "
    "complete outreach sequence some weeks ago and did not reply. You write the "
    "BRIEF for one final, low-pressure message -- instructions to the message "
    "writer, not the message itself. Respond with ONLY a JSON object: "
    '{"brief": "..."} -- no prose, no markdown fences.\n'
    "RULES. The brief is 1-3 sentences. It must name one angle grounded ONLY in "
    "the history and product brief given, and tell the writer to make it easy "
    "for the prospect to say 'not now' or 'no'. Never invent a trigger event, "
    "a mutual connection, a statistic, a deadline, a discount or a name. Never "
    "suggest guilt, urgency, a 'last chance', 'closing your file', or any "
    "reference to the prospect not having replied."
)

FALLBACK_REENGAGEMENT_BRIEF = (
    "One short, low-pressure note. Offer the single most relevant benefit for "
    "this company in one line, and ask whether it is worth a conversation now "
    "or better left for later -- make 'not now' an easy answer. No reference "
    "to earlier messages going unanswered."
)


def build_reengagement_brief(
    session: Session,
    strategy: Strategy,
    lead: Lead,
    *,
    channel: str = "email",
    max_history: int = 3,
) -> str:
    """The brief for a Feature 5 re-engagement message. Never raises: a failed
    model call falls back to FALLBACK_REENGAGEMENT_BRIEF, which the ordinary
    render path still personalizes against the lead's real data."""
    from app.db.models import Message, Outcome, Product  # noqa: PLC0415

    sent = session.execute(
        select(Message)
        .where(Message.lead_id == lead.id, Message.body.isnot(None))
        .order_by(Message.step_no)
    ).scalars().all()[-max_history:]
    history = "\n\n".join(
        f"[step {m.step_no}, {m.channel.value if m.channel else '?'}] "
        f"{(m.subject or '').strip()}\n{(m.body or '').strip()[:600]}"
        for m in sent
    ) or "(nothing on file)"
    events = session.execute(
        select(Outcome).where(Outcome.lead_id == lead.id).order_by(Outcome.ts)
    ).scalars().all()[-12:]
    outcomes = ", ".join(
        f"{o.event.value if o.event else '?'}"
        f"({o.channel}{', ' + o.ts.date().isoformat() if o.ts else ''})"
        for o in events
    ) or "(no recorded activity)"
    product = session.get(Product, strategy.product_id)
    product_brief = (
        f"{product.name} — {product.description or ''}".strip(" —")
        if product is not None else "(no product on file)"
    )

    try:
        data = get_client().complete_json(
            system=_REENGAGEMENT_SYSTEM,
            prompt=_FOLLOWUP_PROMPT.format(
                notice=prompt_safety.NOTICE,
                # F-AI-02: earlier bodies were model-written from lead data,
                # and the lead fields are scraped -- all delimited. Outcomes
                # (our event enums), product brief and playbook are OURS.
                history=prompt_safety.block(history[:6000]),
                outcomes=outcomes,
                product=product_brief[:1000],
                playbook=_playbook(session, strategy)[:4000],
                full_name=prompt_safety.inline(lead.full_name or "there"),
                title=prompt_safety.inline(lead.title or "unknown"),
                company=prompt_safety.inline(lead.company or "their company"),
                channel=channel,
            ).replace("Write the brief for the next touch now.",
                      "Write the brief for the re-engagement message now."),
            schema=BRIEF_SCHEMA,
        )
        brief = str((data or {}).get("brief") or "").strip()
    except Exception as exc:  # noqa: BLE001 — see the docstring
        logger.warning("re-engagement brief generation failed for lead %s: %s: %s",
                       lead.id, type(exc).__name__, exc)
        brief = ""

    brief = _grounded_brief(brief[:2000], lead, history, product_brief,
                            _playbook(session, strategy))
    return brief or FALLBACK_REENGAGEMENT_BRIEF
